import { useEffect, useMemo, useState } from 'react'
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Brain, Check, ChevronDown, CircleHelp, Clock3, Coins, Copy, Download, Eye, Focus, House, Leaf, LogOut, Moon, Plus, ShieldCheck, Sparkles, Sun, Users, Wallet, X } from 'lucide-react'
import { Area, AreaChart, CartesianGrid, Line, LineChart, PolarAngleAxis, PolarGrid, PolarRadiusAxis, Radar, RadarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { daysAgo, demoGroups, demoUsers, groupType, keyId, roleMap, skills, type Group, type Person, type Role, type Segment, type Session, type Skill } from './model'
import ChatPanel from './ChatPanel'
import GamePanel from './CognitiveGames'
import ChallengePanel from './ChallengePanel'
import FocusSessionPanel from './FocusSessionPanel'

type State={users:Person[];groups:Group[];transactions:{id:string;userId:string;amount:number;reason:string;sessionId?:string;at:string}[]}
const seed:State={users:demoUsers,groups:demoGroups,transactions:demoUsers.map(u=>({id:`seed-${u.id}-1`,userId:u.id,amount:26,reason:'Sample opening balance',at:daysAgo(30)}))}
const read=():State=>{try{const s=localStorage.getItem('mindledger.v1');if(s){const saved=JSON.parse(s) as State;const users=[...saved.users];for(const demo of demoUsers)if(!users.some(p=>p.id===demo.id))users.push(demo);const groups=[...saved.groups];for(const group of demoGroups)if(!groups.some(g=>g.id===group.id))groups.push(group);return{...saved,users,groups}}}catch{}return structuredClone(seed)}
const money=(v:number)=>`${v>0?'+':''}${v}`
const average=(xs:number[])=>xs.length?Math.round(xs.reduce((a,b)=>a+b,0)/xs.length):0
const initials=(s:string)=>s.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()
const experienceFor=(s:Session,existing:Session[]=[] )=>{if(s.challengeId&&existing.some(item=>item.challengeId===s.challengeId))return 0;return s.type==='mission'?(s.xpEarned??Math.round(s.score/10)):s.type==='game'?(s.xpEarned??(s.score>=60?3:0)):0}
const totalExperience=(user:Person)=>Math.max(user.xp||0,user.sessions.reduce((total,session)=>total+(session.xpEarned||0),0))

export default function App(){
 const [db,setDb]=useState<State>(read),[user,setUser]=useState<Person|null>(()=>{try{const id=localStorage.getItem('mindledger.session');return read().users.find(x=>x.id===id)||null}catch{return null}})
 const [page,setPage]=useState<'home'|'segments'|'roles'|'auth'|'dashboard'|'help'|'privacy'|'terms'|'contact'>(()=>localStorage.getItem('mindledger.session')?'dashboard':'home'),[segment,setSegment]=useState<Segment>('Home'),[role,setRole]=useState<Role>('Child'),[authTab,setAuthTab]=useState<'login'|'register'>('login'),[dark,setDark]=useState(localStorage.getItem('mindledger.theme')==='dark'),[section,setSection]=useState('Overview'),[notice,setNotice]=useState(''),[menu,setMenu]=useState(false),[activePerson,setActivePerson]=useState(''),[range,setRange]=useState('7 days')
 useEffect(()=>{localStorage.setItem('mindledger.v1',JSON.stringify(db))},[db]);useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('mindledger.theme',dark?'dark':'light')},[dark]);useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),3600);return()=>clearTimeout(t)}},[notice])
 const refreshUser=(id:string)=>{const p=db.users.find(u=>u.id===id);setUser(p||null)}
 const saveDb=(next:State)=>{setDb(next);if(user){const updated=next.users.find(u=>u.id===user.id);if(updated)setUser(updated)}}
 const logout=()=>{localStorage.removeItem('mindledger.session');setUser(null);setPage('home');setSection('Overview');setMenu(false)}
 const home=()=>{setPage(user?'dashboard':'home');setSection('Overview')}
 const [selectedKid,setSelectedKid]=useState(''),[selectedTeam,setSelectedTeam]=useState('all')
 const managed=useMemo(()=>user?db.users.filter(p=>p.groupId===user.groupId&&p.id!==user.id):[],[db.users,user])
 const personId=(managed.some(p=>p.id===selectedKid)?selectedKid:managed[0]?.id)||''
 const focusTarget=user?.role==='Parent'?managed.find(p=>p.id===personId):user
 const target=focusTarget||user
 const isSupervisor=user?['Parent','HR Manager/Admin','Teacher'].includes(user.role):false
 const peopleForDash=user?.role==='HR Manager/Admin'?managed.filter(p=>selectedTeam==='all'||p.id===selectedTeam):user?.role==='Teacher'?managed:target?[target]:[]
 const mergedSessions=peopleForDash.flatMap(p=>p.sessions).filter(s=>range==='all'||Date.now()-new Date(s.date).getTime()<=(range==='30 days'?30:7)*86400000)
 const summary=useMemo(()=>({attention:average(mergedSessions.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus')).map(s=>s.score)),recall:average(mergedSessions.filter(s=>s.skill==='Memory').map(s=>s.score)),sessions:mergedSessions.length,credits:peopleForDash.reduce((n,p)=>n+p.credits,0)}),[mergedSessions,peopleForDash])
 const chartData=useMemo(()=>Array.from({length:7},(_,ix)=>{const day=new Date(Date.now()-(6-ix)*86400000);const daily=mergedSessions.filter(s=>new Date(s.date).toDateString()===day.toDateString());return{day:day.toLocaleDateString(undefined,{weekday:'short'}),Attention:daily.some(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus'))?average(daily.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus')).map(s=>s.score)):null,Recall:daily.some(s=>s.skill==='Memory')?average(daily.filter(s=>s.skill==='Memory').map(s=>s.score)):null,Earned:daily.reduce((n,s)=>n+s.creditsEarned,0),Debt:average(peopleForDash.flatMap(p=>skills.map(sk=>p.skills[sk].debt))),Repaid:average(peopleForDash.flatMap(p=>skills.map(sk=>p.skills[sk].repaid)))}}),[mergedSessions,peopleForDash])
 const radar=skills.map(skill=>{const people=peopleForDash.map(p=>{const skillSessions=p.sessions.filter(s=>s.skill===skill&&s.type!=='break'&&s.completed!==false);const hasRecordedStats=p.skills[skill].debt>0||p.skills[skill].repaid>0;const observed=skillSessions.length?average(skillSessions.map(s=>s.score)):hasRecordedStats?100-p.skills[skill].debt:0;const dailyGames=new Set(skillSessions.filter(s=>s.type==='game'&&s.challengeId).map(s=>s.challengeId)).size;const practised=Math.max(p.skills[skill].repaid,Math.min(100,dailyGames*2));return{observed,practised}});return{skill,Observed:average(people.map(p=>p.observed)),Practised:average(people.map(p=>p.practised))}})
 const recommendations=useMemo(()=>{if(!target)return[];const list:{title:string;detail:string;icon:string}[]=[];const weak=[...skills].sort((a,b)=>target.skills[b].debt-target.skills[a].debt);if(target.skills[weak[0]].debt>25)list.push({title:`Try a solo ${weak[0].toLowerCase()} practice`,detail:`${weak[0]} has the most observed assistance in your recent activity. Start with five minutes on your own.`,icon:'↗'});if(average(target.sessions.filter(s=>s.skill==='Memory').map(s=>s.score))>70)list.push({title:'Try delayed recall',detail:'Your recent recall practice is trending up. Add a short pause before your next recall.',icon:'⌁'});list.push({title:'Experiment with a shorter focus block',detail:'A 20-minute session can help you notice when your attention starts to wander.',icon:'◷'});return list.slice(0,3)},[target])
 const appendActivity=(p:Person,s:Session,credit:number,reason:string)=>{const users=db.users.map(x=>{if(x.id!==p.id||x.sessions.some(existing=>existing.id===s.id))return x;const xp=experienceFor(s,x.sessions);const recorded={...s,xpEarned:xp};const skill=s.skill||'Focus';const firstChallenge=Boolean(s.challengeId)&&!x.sessions.some(existing=>existing.challengeId===s.challengeId);const firstDailyGame=s.type==='game'&&s.completed===true&&firstChallenge;let nextSkills=x.skills;if(s.type==='mission'&&(!s.challengeId||firstChallenge)){nextSkills={...x.skills,[skill]:{debt:Math.max(0,x.skills[skill].debt-2),repaid:Math.min(100,x.skills[skill].repaid+3)}}}else if(firstDailyGame){const gain=Math.max(1,Math.min(5,Math.floor((s.score-50)/10)));nextSkills={...x.skills,[skill]:{debt:Math.max(0,x.skills[skill].debt-Math.max(1,Math.round(gain/2))),repaid:Math.min(100,x.skills[skill].repaid+gain)}}}else if(s.type==='focus'){nextSkills={...x.skills,[skill]:{debt:Math.max(0,x.skills[skill].debt-1),repaid:Math.min(100,x.skills[skill].repaid+2)}}}return{...x,sessions:[recorded,...x.sessions],credits:x.credits+credit,xp:(x.xp||0)+xp,skills:nextSkills}});saveDb({...db,users,transactions:credit?[{id:keyId(),userId:p.id,amount:credit,reason,sessionId:s.id,at:new Date().toISOString()},...db.transactions]:db.transactions})}
 const beginLogin=()=>{setSegment('Personal');setRole('Individual');setAuthTab('login');setPage('auth')}
 const beginRegistration=(s:Segment,r:Role)=>{setSegment(s);setRole(r);setAuthTab('register');setPage('auth')}

 return <div className="app-shell">
  <header className="topbar"><button className="brand" onClick={home} aria-label="MindLedger home"><span className="brand-mark"><Brain size={20}/></span><span>mindledger<span className="brand-dot">.</span></span></button><nav className="topnav"><button onClick={home}>Home</button><button onClick={()=>setPage('help')}>Help</button>{!user&&<><button onClick={beginLogin}>Log in</button><button onClick={()=>setPage('segments')}>Create account</button></>}</nav><div className="top-actions"><button className="icon-btn theme-toggle" onClick={()=>setDark(!dark)} aria-label={dark?'Switch to light mode':'Switch to dark mode'}>{dark?<Sun size={17}/>:<Moon size={17}/>}</button>{user&&<div className="profile-wrap"><button className="profile-pill" onClick={()=>setMenu(!menu)} aria-expanded={menu}><span className="avatar small">{initials(user.name)}</span><span className="profile-name">{user.name.split(' ')[0]}</span><ChevronDown size={14}/></button>{menu&&<div className="dropdown profile-menu"><button onClick={()=>{setSection('Account');setPage('dashboard');setMenu(false)}}>My Account</button><button onClick={logout}><LogOut size={15}/> Log out</button></div>}</div>}</div></header>
  <main className="main-content">
   {page==='home'&&<Landing onStart={()=>setPage('segments')} onLogin={beginLogin}/>}
   {page==='segments'&&<SegmentPicker onBack={()=>setPage('home')} onPick={(s)=>{setSegment(s);setPage('roles')}}/>}
   {page==='roles'&&<RolePicker segment={segment} onBack={()=>setPage('segments')} onPick={r=>beginRegistration(segment,r)}/>}
   {page==='auth'&&<AuthPage segment={segment} role={role} tab={authTab} setTab={setAuthTab} db={db} onBack={()=>authTab==='register'?setPage('roles'):setPage('home')} onCreateAccount={()=>setPage('segments')} onLogin={(p)=>{setUser(p);localStorage.setItem('mindledger.session',p.id);setPage('dashboard');setSection('Overview');setNotice(`Welcome back, ${p.name.split(' ')[0]}.`);setActivePerson(p.id)}} onSave={saveDb} notify={setNotice}/>}
   {(page==='help'||page==='privacy'||page==='terms'||page==='contact')&&<InfoPage page={page} back={home}/>}
    {page==='dashboard'&&user&&<>
    <div className="dash-head"><div><div className="eyebrow">{user.role==='Parent'?'FAMILY SPACE':user.role==='HR Manager/Admin'?'WORKPLACE INSIGHTS':user.role==='Teacher'?'CLASSROOM SPACE':'YOUR SPACE'} <span className="sample-tag">DEMO DATA</span></div><h1>{user.role==='Parent'?'A little progress, every day.':user.role==='HR Manager/Admin'?'Learning grows with good habits.':user.role==='Teacher'?'Support every learner.':`Good ${new Date().getHours()<12?'morning':'day'}, ${user.name.split(' ')[0]}.`}</h1><p className="subhead">{isSupervisor?'See skills, practice patterns, and progress at a glance.':'Build focus and confidence through small, independent steps.'}</p></div>{user.role==='Parent'&&<label className="select-wrap"><span>CHILD</span><select aria-label="Select child" value={personId} onChange={e=>setSelectedKid(e.target.value)}>{managed.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label>}{user.role==='HR Manager/Admin'&&<label className="select-wrap"><span>TEAM VIEW</span><select aria-label="Select team member" value={selectedTeam} onChange={e=>setSelectedTeam(e.target.value)}><option value="all">All workers</option>{managed.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label>}{user.role==='Teacher'&&<label className="select-wrap"><span>CLASS</span><select aria-label="Select class" value={user.groupId} onChange={()=>{}}><option>{db.groups.find(g=>g.id===user.groupId)?.name||'Class'}</option></select></label>}</div>
    {section==='Account'?<Account user={user} onLogout={logout}/>:user.role==='Parent'||user.role==='HR Manager/Admin'||user.role==='Teacher'?<SupervisorDash key={`${user.id}-${personId}-${selectedTeam}-${range}`} role={user.role} people={peopleForDash} allManaged={managed} target={target} summary={summary} chartData={chartData} radar={radar} range={range} setRange={setRange} recommendations={recommendations} user={user} onComplete={s=>{const reward=s.creditsEarned;appendActivity(user,s,reward,s.type==='break'?'Eligible break completed':s.type==='focus'?'Focus session completed':'Challenge completed');const xp=experienceFor(s,user.sessions);setNotice(xp?(s.type==='mission'?'Challenge complete':'Game won')+'! '+xp+' XP earned.'+(reward?' '+reward+' Think Credits earned.':''):reward?'Session saved. '+reward+' Think Credits earned.':'Focus session saved. Keep showing up.')}} notify={setNotice} groupCode={db.groups.find(g=>g.id===user.groupId)?.code||''} onInvite={()=>{setSection('Invite');setNotice('Share this group code with a member.')}} onExport={()=>exportCSV(peopleForDash)} section={section} setSection={setSection} db={db} saveDb={saveDb}/>:<MemberDash key={`${user.id}-${section}`} user={user} section={section} setSection={setSection} recommendations={recommendations} chartData={chartData} radar={radar} onComplete={s=>{const reward=s.creditsEarned;appendActivity(user,s,reward,s.type==='break'?'Eligible break completed':s.type==='focus'?'Focus session completed':'Challenge completed');const xp=experienceFor(s,user.sessions);setNotice(xp?`${s.type==='mission'?'Challenge complete':'Game won'}! ${xp} XP earned.${reward?` ${reward} Think Credits earned.`:''}`:reward?`Session saved. ${reward} Think Credits earned.`:'Focus session saved. Keep showing up.')}} db={db} saveDb={saveDb} notify={setNotice}/>}
   </>}
  </main>
  <footer className="footerbar"><span>© 2026 MindLedger. All rights reserved.</span><div><button onClick={()=>setPage('privacy')}>Privacy</button><button onClick={()=>setPage('terms')}>Terms</button><button onClick={()=>setPage('contact')}>Contact</button></div></footer>
  {notice&&<div className="toast" role="status"><Check size={16}/>{notice}<button onClick={()=>setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}
 </div>
}

function Landing({onStart,onLogin}:{onStart:()=>void;onLogin:()=>void}){return <section className="hero"><div className="hero-copy"><span className="eyebrow"><span className="live-dot"/> THINK WELL, EVERY DAY</span><h1>Unlimited AI,<br/><em>earned by thinking.</em></h1><p>Build focus, memory, and confidence with small, meaningful moments of independent thought.</p><div className="button-row"><button className="btn btn-primary btn-large" onClick={onStart}>Create account <ArrowRight size={17}/></button><button className="btn btn-secondary btn-large" onClick={onLogin}>Log in</button></div><div className="hero-proof"><span><ShieldCheck size={15}/> Private by design</span><span><Leaf size={15}/> Progress over pressure</span></div></div><div className="hero-art"><div className="orb orb-a"/><div className="orb orb-b"/><div className="hero-card balance-float"><div className="mini-card-head"><div className="mini-icon teal"><Brain size={18}/></div><span className="quiet">THIS WEEK</span></div><div className="float-score">72<span>/100</span></div><div className="sparkline"><i/><i/><i/><i/><i/><i/><i/></div><div className="float-foot"><span>Independent thinking</span><span className="up-chip"><ArrowUpRight size={13}/> 8%</span></div></div><div className="hero-card credit-float"><div className="mini-icon amber"><Sparkles size={17}/></div><div><strong>Think Credits</strong><span>Earned by showing up</span></div><span className="credit-count">+12</span></div><div className="hero-seal"><div className="seal-circle"><Focus size={25}/></div><span>little steps<br/>add up</span></div></div><div className="hero-bottom"><span className="hero-count">01 <i/> 03</span><span className="quiet">A calmer way to grow with AI</span></div></section>}
function SegmentPicker({onBack,onPick}:{onBack:()=>void;onPick:(s:Segment)=>void}){const opts:[Segment,string,string,string][]=[['Personal','Grow at your own pace','For independent learners and everyday thinkers','✦'],['Home','Build healthy habits together','For families growing curious minds','⌂'],['Corporate','Make room for focused work','For teams that value learning','◒'],['School','Strengthen independent learning','For classrooms growing confidence','▤']];return <section className="flow-page"><button className="back-link" onClick={onBack}>← Back</button><div className="center-heading"><span className="eyebrow">A SPACE FOR EVERY KIND OF GROWTH</span><h1>Who is this for?</h1><p>Choose the space you’re here to support.</p></div><div className="segment-grid">{opts.map(([name,title,detail,icon])=><button className="segment-card" key={name} onClick={()=>onPick(name)}><span className="segment-icon">{icon}</span><span className="segment-label">{name}</span><strong>{title}</strong><small>{detail}</small><span className="segment-arrow"><ArrowRight size={17}/></span></button>)}</div><div className="flow-note"><ShieldCheck size={15}/> Your workspace stays private to your family, team, or class.</div></section>}
function RolePicker({segment,onBack,onPick}:{segment:Segment;onBack:()=>void;onPick:(r:Role)=>void}){const desc:Record<Role,string>={Individual:'Use MindLedger on your own. No group invitation needed.',Parent:'Create a family space and support children.',Child:'Practice skills at your own pace.', 'HR Manager/Admin':'Create a team space and view aggregate trends.',Worker:'Build focus and learning habits at work.',Teacher:'Set up a class and support learners.',Student:'Grow confidence through practice.'};return <section className="flow-page"><button className="back-link" onClick={onBack}>← Back to spaces</button><div className="center-heading"><span className="eyebrow">{segment.toUpperCase()} SPACE</span><h1>Choose your role</h1><p>We’ll tailor your workspace to what you need.</p></div><div className="role-list">{roleMap[segment].map(r=><button className="role-row" onClick={()=>onPick(r)} key={r}><span className="role-avatar">{initials(r)}</span><span className="role-copy"><strong>{r}</strong><small>{desc[r]}</small></span><ArrowRight size={17}/></button>)}</div></section>}

function AuthPage({segment,role,tab,setTab,db,onBack,onCreateAccount,onLogin,onSave,notify}:{segment:Segment;role:Role;tab:'login'|'register';setTab:(x:'login'|'register')=>void;db:State;onBack:()=>void;onCreateAccount:()=>void;onLogin:(p:Person)=>void;onSave:(d:State)=>void;notify:(s:string)=>void}){
 const supervisor=['Parent','HR Manager/Admin','Teacher'].includes(role);const [form,setForm]=useState({name:'',email:'',password:'',code:'',groupName:'',age:'',grade:''}),[error,setError]=useState(''),[created,setCreated]=useState(''),[createdPerson,setCreatedPerson]=useState<Person|null>(null);const change=(k:keyof typeof form,v:string)=>setForm({...form,[k]:v});const update=(k:keyof typeof form)=>(e:React.ChangeEvent<HTMLInputElement|HTMLSelectElement>)=>change(k,e.target.value);const demoAccounts=db.users.filter(p=>p.email.endsWith('@mindledger.demo'))
 const login=(e:React.FormEvent)=>{e.preventDefault();setError('');const account=form.email.trim().toLowerCase();const p=db.users.find(x=>(x.email.toLowerCase()===account||x.id.toLowerCase()===account)&&x.password===form.password);if(!p){setError('We couldn’t find that account and password. Check your details or create an account.');return}onLogin(p)}
 const register=(e:React.FormEvent)=>{e.preventDefault();setError('');if(!form.name.trim()||!form.email.trim()||form.password.length<8){setError('Add your name and email. Passwords need at least 8 characters.');return}if(db.users.some(x=>x.email.toLowerCase()===form.email.trim().toLowerCase())){setError('That email is already registered. Try signing in instead.');return}const id=keyId();let group:Group|undefined
 if(supervisor){if(!form.groupName.trim()){setError(`Enter a ${segment==='Home'?'family':segment==='Corporate'?'company':'class'} name.`);return}group={id:keyId(),type:groupType(segment),name:form.groupName.trim(),code:`${segment==='Home'?'FAM':segment==='Corporate'?'TEAM':'CLASS'}-${Math.floor(1000+Math.random()*9000)}`,ownerId:id,grade:form.grade||undefined}}
 else if(role!=='Individual') {const code=form.code.trim().toUpperCase();group=db.groups.find(g=>g.type===groupType(segment)&&g.code.toUpperCase()===code);if(!group){setError(`That invitation code was not found. Ask your ${segment==='Home'?'parent':segment==='Corporate'?'admin':'teacher'} for the correct code.`);return}if(role==='Child'&&(!form.age||Number(form.age)<5||Number(form.age)>18)){setError('Enter an age from 5 to 18.');return}}
 const person:Person={id,name:form.name.trim(),email:form.email.trim(),password:form.password,role,segment,groupId:group?.id||'',age:role==='Child'?Number(form.age):undefined,credits:0,skills:Object.fromEntries(skills.map(s=>[s,{debt:0,repaid:0}])) as Person['skills'],sessions:[],createdAt:new Date().toISOString()};const users=[...db.users,person];let groups=group&&supervisor?[...db.groups,group]:db.groups;if(group&&supervisor){const ownerGroup={...group,ownerId:id};groups=[...db.groups,ownerGroup]};onSave({...db,users,groups});if(supervisor){setCreated(group!.code);setCreatedPerson(person);setError('');return}onLogin(person)
 }
 const copy=()=>{navigator.clipboard?.writeText(created);notify('Invitation code copied.')};return <section className="auth-layout"><div className="auth-aside"><button className="back-link" onClick={onBack}>← Back</button><span className="eyebrow">{tab==='login'?'MINDLEDGER ACCOUNT':`${segment.toUpperCase()} · ${role.toUpperCase()}`}</span><h1>{tab==='login'?'Welcome back.':supervisor?'Start your space.':'Find your starting point.'}</h1><p>{tab==='login'?'One account, with your own private progress and tools.':supervisor?'Create an account and invite your family, team, or class.':'Join your group or sign in to continue your practice.'}</p><div className="auth-quote"><span>“</span><p>Progress comes from practice, not perfection.</p><small>THE MINDLEDGER PRINCIPLE</small></div></div><div className="auth-card"><div className="auth-tabs"><button className={tab==='login'?'active':''} onClick={()=>{if(tab!=='login'){setTab('login');setError('');setCreated('')}}}>Log in</button><button className={tab==='register'?'active':''} onClick={()=>{if(tab!=='register')onCreateAccount()}}>Create account</button></div>{created?<div className="created-code"><span className="check-bubble"><Check/></span><h2>Your space is ready</h2><p>Share this code so your members can join.</p><div className="code-display"><strong>{created}</strong><button className="icon-btn" onClick={copy} aria-label="Copy invitation code"><Copy size={17}/></button></div><small>Members only see shared progress. Private answers and reflections stay theirs.</small><button className="btn btn-primary full-btn" onClick={()=>createdPerson&&onLogin(createdPerson)}>Go to my dashboard <ArrowRight size={16}/></button></div>:tab==='login'?<form onSubmit={login} className="form-stack"><h2>Welcome back</h2><p className="form-intro">Sign in to your MindLedger account.</p><Field label="Email or account ID" value={form.email} onChange={update('email')} placeholder="you@example.com"/><Field label="Password" value={form.password} onChange={update('password')} type="password" placeholder="At least 8 characters"/>{demoAccounts.length>0&&<label className="field"><span>Quick fill a demo profile</span><select value="" onChange={e=>{const chosen=demoAccounts.find(p=>p.id===e.target.value);if(chosen){change('email',chosen.email);change('password',chosen.password)}}}><option value="">Choose an account…</option>{demoAccounts.map(p=><option key={p.id} value={p.id}>{p.name} · {p.role}</option>)}</select></label>}{error&&<div className="form-error" role="alert">{error}</div>}<button className="btn btn-primary full-btn" type="submit">Log in <ArrowRight size={16}/></button><p className="simulated-note"><ShieldCheck size={14}/> Quick fill uses seeded demo accounts. Authentication in this local prototype is simulated.</p></form>:<form onSubmit={register} className="form-stack"><h2>Create your account</h2><p className="form-intro">{supervisor?'Set up your '+(segment==='Home'?'family':segment==='Corporate'?'company':'class')+' space.':role==='Individual'?'Create a personal account; no invitation code is needed.':'Join the right group to get started.'}</p><div className="form-two"><Field label="Your name" value={form.name} onChange={update('name')} placeholder="Full name"/><Field label="Email" value={form.email} onChange={update('email')} placeholder="you@example.com"/></div><Field label="Password" value={form.password} onChange={update('password')} type="password" placeholder="At least 8 characters"/>{supervisor?<><Field label={segment==='Home'?'Family name':segment==='Corporate'?'Company name':'Class name'} value={form.groupName} onChange={update('groupName')} placeholder={segment==='Home'?'The Lee family':segment==='Corporate'?'Your company':'Grade 8 · Cedar'}/>{segment==='School'&&<Field label="Grade" value={form.grade} onChange={update('grade')} placeholder="e.g. 8"/>}</>:role==='Individual'?null:<><Field label={role==='Child'?'Child ID / Family code':role==='Worker'?'Company code':'Class code'} value={form.code} onChange={update('code')} placeholder="Enter the code from your supervisor"/>{role==='Child'&&<Field label="Age" value={form.age} onChange={update('age')} type="number" placeholder="5–18"/>}<p className="hint">Need a code? Ask your {role==='Child'?'parent':role==='Worker'?'admin':'teacher'} to share the group invitation.</p></>}{error&&<div className="form-error" role="alert">{error}</div>}<button className="btn btn-primary full-btn" type="submit">{supervisor?'Create my space':'Join my group'} <ArrowRight size={16}/></button><p className="simulated-note"><ShieldCheck size={14}/> Demo authentication is simulated. Do not use a real password.</p></form>}</div></section>}
function Field({label,value,onChange,type='text',placeholder}:{label:string;value:string;onChange:(e:React.ChangeEvent<HTMLInputElement>)=>void;type?:string;placeholder?:string}){return <label className="field"><span>{label}</span><input value={value} onChange={onChange} type={type} placeholder={placeholder} required /></label>}
function InfoPage({page,back}:{page:string;back:()=>void}){const details:Record<string,[string,string]>={help:['We’re here to help.','For this prototype, reach the MindLedger team at hello@mindledger.example. If you are joining a family, team, or class, ask your supervisor for its invitation code.'],privacy:['Your thinking stays yours.','Challenge responses and personal reflections are stored only in your local browser demo. Supervisor views show activity, scores, and trends only. This prototype has no production authentication or remote data storage.'],terms:['A note about the prototype.','MindLedger’s cognitive debt indicator is an experimental summary of observed assistance and practice patterns. It is not a validated psychological, educational, or medical measure.'],contact:['Let’s talk.','Email hello@mindledger.example. This is a demo address; contact delivery is not connected in this prototype.']};return <section className="info-page"><button className="back-link" onClick={back}>← Home</button><span className="eyebrow">MINDLEDGER</span><h1>{details[page][0]}</h1><p>{details[page][1]}</p><button className="btn btn-secondary" onClick={back}>Back to MindLedger</button></section>}
function Account({user,onLogout}:{user:Person;onLogout:()=>void}){return <div className="account-card card"><div className="avatar large">{initials(user.name)}</div><div><span className="eyebrow">MY ACCOUNT</span><h2>{user.name}</h2><p>{user.email} · {user.role}</p><p className="muted">Local demo account · Created {new Date(user.createdAt).toLocaleDateString()}</p><div className="button-row"><button className="btn btn-quiet" onClick={onLogout}>Log out</button></div></div></div>}
function exportCSV(people:Person[]){const rows=[['Name','Role','Sessions','Attention avg','Recall avg','Think Credits'],...people.map(p=>[p.name,p.role,String(p.sessions.length),String(average(p.sessions.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus')).map(s=>s.score))),String(average(p.sessions.filter(s=>s.skill==='Memory').map(s=>s.score))),String(p.credits)])];const blob=new Blob([rows.map(r=>r.map(x=>`"${x.replaceAll('"','""')}"`).join(',')).join('\r\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mindledger-summary.csv';a.click();URL.revokeObjectURL(a.href)}

function SupervisorDash({user,onComplete,notify,role,people,allManaged,target,summary,chartData,radar,range,setRange,recommendations,onInvite,onExport,groupCode,section,setSection,db,saveDb}:{role:Role;people:Person[];allManaged:Person[];target:Person|null;summary:{attention:number;recall:number;sessions:number;credits:number};chartData:{day:string;Attention:number|null;Recall:number|null;Earned:number;Debt:number;Repaid:number}[];radar:{skill:string;Observed:number;Practised:number}[];range:string;setRange:(x:string)=>void;recommendations:{title:string;detail:string;icon:string}[];onInvite:()=>void;onExport:()=>void;groupCode:string;section:string;setSection:(x:string)=>void;db:State;saveDb:(s:State)=>void;user:Person;onComplete:(s:Session)=>void;notify:(s:string)=>void}){
 const [search,setSearch]=useState('');const student=role==='Teacher',parent=role==='Parent',unit=parent?'children':student?'students':'workers';const observed=people.flatMap(p=>skills.map(s=>p.skills[s].debt));const debt=average(observed),repaid=average(people.flatMap(p=>skills.map(s=>p.skills[s].repaid)));const attention=summary.attention||71,recall=summary.recall||74;const perSkill=skills.map(s=>({skill:s,avg:average(people.map(p=>100-p.skills[s].debt)),debt:average(people.map(p=>p.skills[s].debt))}));const support=people.filter(p=>Math.max(...skills.map(s=>p.skills[s].debt))>35);const supervisorSections=['Overview','Balance sheet','Cognitive Games','AI Coach','Challenges','Focus session','Wander break','Credits','Progress','People','Suggestions'];const breakToday=db.transactions.filter(t=>t.userId===user.id&&t.reason==='Eligible break completed'&&new Date(t.at).toDateString()===new Date().toDateString()).length;const spent=db.transactions.filter(t=>t.userId===user.id&&t.amount<0).reduce((n,t)=>n-t.amount,0);const personalChartData=Array.from({length:7},(_,ix)=>{const day=new Date(Date.now()-(6-ix)*86400000);const daily=user.sessions.filter(s=>new Date(s.date).toDateString()===day.toDateString());const attentionRows=daily.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus'));const recallRows=daily.filter(s=>s.skill==='Memory');return{day:day.toLocaleDateString(undefined,{weekday:'short'}),Attention:attentionRows.length?average(attentionRows.map(s=>s.score)):null,Recall:recallRows.length?average(recallRows.map(s=>s.score)):null,Earned:daily.reduce((n,s)=>n+s.creditsEarned,0),Debt:average(skills.map(sk=>user.skills[sk].debt)),Repaid:average(skills.map(sk=>user.skills[sk].repaid))}});const personalRadar=skills.map(skill=>{const rows=user.sessions.filter(s=>s.skill===skill);return{skill,Observed:rows.length?average(rows.map(s=>s.score)):Math.max(0,100-user.skills[skill].debt),Practised:user.skills[skill].repaid}});
 if(section==='Invite')return <div className="invite-panel card"><button className="back-link" onClick={()=>setSection('Overview')}>← Back to dashboard</button><span className="eyebrow">INVITE A MEMBER</span><h2>Share your group code</h2><p>Members can create an account with this code. It links their account to your {parent?'family':student?'class':'company'} group.</p><div className="code-display"><strong>{groupCode||'Group code unavailable'}</strong><span>Use the code displayed in account setup</span></div><button onClick={()=>navigator.clipboard?.writeText(groupCode)} className="btn btn-secondary"><Copy size={16}/> Copy group code</button></div>;
 return <div className="dashboard-layout"><aside className="side-nav"><div className="side-label">YOUR SPACE</div>{supervisorSections.map((s,i)=><button key={s} onClick={()=>setSection(s)} className={section===s?'selected':''}><span className="nav-symbol">{['⌂','◉','✳','◷','☼','◇','⌁','◈','▥','♧','✧'][i]}</span><span>{s}</span></button>)}<div className="side-divider"/><div className="privacy-card"><ShieldCheck size={17}/><span>Private by design</span><small>Challenge responses and reflections belong to each person and are never shown here.</small></div><div className="side-bottom">MINDLEDGER · {role.toUpperCase()}</div></aside><section className="dash-body">
    {section==='AI Coach'?<div className="embedded-chat"><ChatPanel key={section} userId={user.id}/></div>:section==='Cognitive Games'?<GamePanel key={user.id} userId={user.id} userName={user.name} attempts={user.sessions} onComplete={onComplete}/>:section==='Balance sheet'?<BalanceSheet user={user} setSection={setSection}/>:section==='Challenges'?<ChallengePanel user={user} onComplete={onComplete} onOpenCoach={()=>setSection('AI Coach')} notify={notify}/>:section==='Focus session'?<FocusSessionPanel user={user} onComplete={onComplete}/>:section==='Wander break'?<BreakSession user={user} onComplete={onComplete} rewardedToday={breakToday}/>:section==='Credits'?<Credits user={user} transactions={db.transactions.filter(t=>t.userId===user.id)} onSpend={(cost,level)=>{if(user.credits<cost){notify('Not enough Think Credits for that assistance level.');return}saveDb({...db,users:db.users.map(p=>p.id===user.id?{...p,credits:p.credits-cost}:p),transactions:[{id:keyId(),userId:user.id,amount:-cost,reason:`AI assistance · ${level}`,at:new Date().toISOString()},...db.transactions]});notify(`${cost} credits used. External AI access is not included.`)}}/>:section==='Progress'?<ProgressView user={user} chartData={personalChartData} radar={personalRadar}/>:section==='Suggestions'?<><div className="section-head"><div><span className="eyebrow">SUGGESTED IMPROVEMENTS</span><h2>Small steps for a stronger space.</h2></div></div><RecommendationList items={recommendations}/></>:section==='People'?<><div className="section-head"><div><span className="eyebrow">{parent?'CHILDREN':student?'LEARNERS':'TEAM MEMBERS'}</span><h2>{allManaged.length} {unit}</h2></div><div className="button-row"><input className="table-search" aria-label="Search members" placeholder="Search name…" value={search} onChange={e=>setSearch(e.target.value)}/><button className="btn btn-secondary" onClick={onExport}><Download size={15}/> Export CSV</button><button className="btn btn-primary" onClick={onInvite}><Plus size={16}/> Invite</button></div></div><div className="people-table card"><div className="table-head"><span>MEMBER</span><span>ATTENTION</span><span>RECALL</span><span>PRACTICE</span><span>ACTIVITY</span></div>{allManaged.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=><div className="table-row" key={p.id}><div className="person-cell"><span className="avatar small">{initials(p.name)}</span><span><b>{p.name}</b><small>{p.role}{p.age?` · ${p.age} yrs`:""}</small><button className="text-action id-copy" title="Copy member ID" onClick={()=>navigator.clipboard?.writeText(p.id)}><Copy size={10}/> ID {p.id.slice(0,8).toUpperCase()}</button></span></div><span>{average(p.sessions.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus')).map(s=>s.score))||'—'}<small>/100</small></span><span>{average(p.sessions.filter(s=>s.skill==='Memory').map(s=>s.score))||'—'}<small>/100</small></span><span>{p.sessions.length} sessions</span><span>{p.sessions.length?new Date(p.sessions[0].date).toLocaleDateString():'No activity'}</span></div>)}</div><p className="privacy-foot"><ShieldCheck size={14}/> No private challenge responses or reflections are available to supervisors.</p></>:role==='Individual'?null:<>
  <div className="section-head"><div><span className="eyebrow">OVERVIEW · {parent?'FAMILY':student?'CLASS':'TEAM'}</span><h2>{parent?(target?.name||'Member')+'’s progress':student?'Class progress':'Team patterns'}</h2></div><div className="head-actions"><label className="select-wrap compact"><span>DATE RANGE</span><select value={range} onChange={e=>setRange(e.target.value)}><option>7 days</option><option>30 days</option><option>all</option></select></label>{!parent&&<button className="btn btn-secondary export-btn" onClick={onExport}><Download size={15}/> CSV</button>}{parent&&<button className="btn btn-secondary" onClick={onInvite}><Plus size={16}/> Add {unit==='workers'?'worker':'child'}</button>}</div></div>
  <LevelProgress xp={totalExperience(user)}/>
  <div className="metric-grid four"><Metric label={student?'CLASS ATTENTION':'AVERAGE ATTENTION'} value={`${attention}`} unit="/100" delta="observed sessions" tone="teal" icon={<Focus size={17}/>}/><Metric label={student?'CLASS RECALL':'AVERAGE RECALL'} value={`${recall}`} unit="/100" delta="memory practice" tone="violet" icon={<Brain size={17}/>}/><Metric label="PRACTICE SESSIONS" value={`${summary.sessions||people.length*4}`} unit="" delta="in selected range" tone="blue" icon={<Activity size={17}/>}/><Metric label="DEBT / REPAYMENT" value={`${debt}%`} unit="" delta={`${repaid}% independent practice`} tone="rose" icon={<ArrowDownRight size={17}/>}/></div>
  <div className="chart-grid supervisor-charts"><ChartCard title="Attention & recall" subtitle="Average score by day" range={range}><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="var(--line)"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis hide domain={[0,100]}/><Tooltip contentStyle={{borderRadius:12,border:'1px solid var(--line)',background:'var(--card)',color:'var(--text)'}}/><Line type="monotone" dataKey="Attention" stroke="var(--teal)" strokeWidth={2.5} dot={false}/><Line type="monotone" dataKey="Recall" stroke="var(--violet)" strokeWidth={2.5} dot={false}/></LineChart></ResponsiveContainer></ChartCard><ChartCard title="Skills at a glance" subtitle="Observed independence across five skills"><ResponsiveContainer width="100%" height="100%"><RadarChart data={radar}><PolarGrid stroke="var(--line)"/><PolarAngleAxis dataKey="skill" tick={{fill:'var(--muted)',fontSize:10}}/><PolarRadiusAxis domain={[0,100]} tick={false} axisLine={false}/><Radar dataKey="Observed" stroke="var(--teal)" fill="var(--teal)" fillOpacity={0.18}/><Radar dataKey="Practised" stroke="var(--amber)" fill="var(--amber)" fillOpacity={0.12}/><Tooltip/></RadarChart></ResponsiveContainer><div className="chart-legend"><i className="teal-dot"/> observed independence <i className="amber-dot"/> practice</div></ChartCard></div>
  <div className="chart-grid lower-grid"><div className="card activity-card"><div className="card-heading"><div><h3>Weekly activity</h3><p>Completed practice sessions</p></div><span className="metric-icon teal"><Activity size={17}/></span></div><div className="weekly-bars">{chartData.map((d,i)=><div className="bar-column" key={i}><span style={{height:`${Math.max(10,Math.min(100,d.Earned*18+24))}%`}}/><small>{d.day}</small></div>)}</div></div><div className="support-card card"><div className="card-heading"><div><h3>{student?'May benefit from support':'Recovery indicators'}</h3><p>{student?'Practice trends that could use attention':'Estimates from voluntary app sessions'}</p></div><span className="metric-icon rose"><Eye size={17}/></span></div><div className="indicator-row"><span>{student?'Learners with high observed skill debt':'Long sessions without a recorded break'}</span><b>{student?support.length:Math.max(0,people.filter(p=>p.sessions.filter(s=>s.type==='focus').length>3).length)}</b></div><div className="indicator-row"><span>Inactivity alerts</span><b>{people.filter(p=>!p.sessions.length).length}</b></div><p className="disclaimer">Non-diagnostic observations only. App activity cannot determine wellbeing or prove that a person has rested.</p></div></div>
  <div className="bottom-panels"><div className="card skill-list-card"><div className="card-heading"><div><h3>{student?'Unaided learning':'Observed skills'}</h3><p>{student?'Reported independent-solve rate':'Patterns across selected '+unit}</p></div><span className="metric-icon amber"><Brain size={17}/></span></div>{perSkill.map(s=><div className="skill-row" key={s.skill}><span>{s.skill}</span><div className="progress-track"><i style={{width:`${s.avg}%`}}/></div><b>{s.avg}%</b></div>)}{student&&<div className="unaided-row"><span>Unaided-solve rate</span><b>{Math.max(0,100-debt)}%</b><small>Prototype estimate from reported practice</small></div>}</div><div className="card recommendations-card"><div className="card-heading"><div><h3>Suggested Improvements</h3><p>Transparent ideas from the available trends</p></div><button className="text-action" onClick={()=>setSection('Suggestions')}>View all <ArrowRight size={14}/></button></div><RecommendationList items={recommendations.slice(0,2)}/><p className="privacy-foot"><ShieldCheck size={14}/> Private answers stay private.</p></div></div>
 </>}
 </section></div>
}
function RecommendationList({items}:{items:{title:string;detail:string;icon:string}[]}){return <div className="recommendation-list">{items.map((r,i)=><div className="recommendation" key={i}><span className="rec-icon">{r.icon}</span><div><strong>{r.title}</strong><p>{r.detail}</p></div><ArrowRight size={15}/></div>)}</div>}
function LevelProgress({xp}:{xp:number}){const level=Math.floor(xp/100)+1;const progress=xp%100;return <div className="level-progress card"><div className="level-badge"><Sparkles size={19}/></div><div className="level-copy"><div className="level-topline"><b>Level {level}</b><span>{xp} total XP</span></div><div className="level-track" role="progressbar" aria-label={`Progress to level ${level+1}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress}><i style={{width:`${progress}%`}}/></div><small>{progress}/100 XP · {100-progress} XP to Level {level+1}</small></div></div>}
function Metric({label,value,unit,delta,tone,icon}:{label:string;value:string;unit:string;delta:string;tone:string;icon:React.ReactNode}){return <div className="metric-card card"><div className="metric-top"><span>{label}</span><span className={`metric-icon ${tone}`}>{icon}</span></div><div className="metric-value">{value}<small>{unit}</small></div><div className="metric-delta">{delta}</div></div>}
function ChartCard({title,subtitle,children,range}:{title:string;subtitle:string;children:React.ReactNode;range?:string}){return <div className="chart-card card"><div className="card-heading"><div><h3>{title}</h3><p>{subtitle}</p></div>{range&&<span className="quiet">{range}</span>}</div><div className="chart-area">{children}</div></div>}

function MemberDash({user,section,setSection,recommendations,chartData,radar,onComplete,db,saveDb,notify}:{user:Person;section:string;setSection:(s:string)=>void;recommendations:{title:string;detail:string;icon:string}[];chartData:{day:string;Attention:number|null;Recall:number|null;Earned:number;Debt:number;Repaid:number}[];radar:{skill:string;Observed:number;Practised:number}[];onComplete:(s:Session)=>void;db:State;saveDb:(s:State)=>void;notify:(s:string)=>void}){
 const tabs=['Overview','Balance sheet','Cognitive Games','AI Coach','Challenges','Focus session','Wander break','Credits','Progress'];const sessions=user.sessions;const balance=sessions.reduce((n,s)=>n+s.creditsEarned,0);const spent=db.transactions.filter(t=>t.userId===user.id&&t.amount<0).reduce((n,t)=>n-t.amount,0);const debt=average(skills.map(s=>user.skills[s].debt));const repaid=average(skills.map(s=>user.skills[s].repaid));const breakToday=db.transactions.filter(t=>t.userId===user.id&&t.reason==='Eligible break completed'&&new Date(t.at).toDateString()===new Date().toDateString()).length;
 return <div className="dashboard-layout"><aside className="side-nav"><div className="side-label">YOUR SPACE</div>{tabs.map((s,i)=><button key={s} onClick={()=>setSection(s)} className={section===s?'selected':''}><span className="nav-symbol">{['⌂','◉','✳','◷','☼','◇','⌁'][i]}</span><span>{s}</span></button>)}<div className="side-divider"/><div className="wallet-mini"><span><Coins size={16}/> THINK CREDITS</span><b>{user.credits}</b><small>available now</small></div><div className="side-bottom">A LITTLE PROGRESS, DAILY</div></aside><section className="dash-body member-body">
   {section==='Overview'&&<><div className="section-head"><div><span className="eyebrow">YOUR COGNITIVE BALANCE</span><h2>Practice that adds up.</h2><p className="section-sub">Debt is an experimental summary of observed assistance patterns. Practice helps build your independent skill record.</p></div><button className="btn btn-primary" onClick={()=>setSection('Challenges')}>Choose a challenge <ArrowRight size={15}/></button></div><LevelProgress xp={totalExperience(user)}/><div className="home-coach-cta card"><div className="home-coach-mark"><Sparkles size={22}/></div><div className="home-coach-copy"><span className="eyebrow">YOUR NEXT STEP</span><h3>What would you like to work through?</h3><p>Your AI Coach is the place to think, learn, and get answers.</p></div><button className="btn btn-primary btn-large" onClick={()=>setSection('AI Coach')}>Open AI Coach <ArrowRight size={16}/></button></div><div className="metric-grid four"><Metric label="THINK CREDITS" value={`${user.credits}`} unit="" delta={`+${balance} earned · ${spent} spent`} tone="amber" icon={<Coins size={17}/>}/><Metric label="OBSERVED DEBT" value={`${debt}`} unit="/100" delta="experimental indicator" tone="rose" icon={<ArrowDownRight size={17}/>}/><Metric label="PRACTICE REPAYMENT" value={`${repaid}`} unit="/100" delta="independent practice" tone="teal" icon={<ArrowUpRight size={17}/>}/><Metric label="SESSIONS THIS WEEK" value={`${sessions.filter(s=>Date.now()-new Date(s.date).getTime()<7*86400000).length}`} unit="" delta="challenges + focus" tone="blue" icon={<Activity size={17}/>}/></div><div className="chart-grid"><ChartCard title="Your attention" subtitle="Focus Rush and focus-session scores"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="mintArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--teal)" stopOpacity={.25}/><stop offset="100%" stopColor="var(--teal)" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="var(--line)"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis hide domain={[0,100]}/><Tooltip contentStyle={{borderRadius:12,border:'1px solid var(--line)',background:'var(--card)',color:'var(--text)'}}/><Area type="monotone" dataKey="Attention" stroke="var(--teal)" strokeWidth={2.5} fill="url(#mintArea)"/></AreaChart></ResponsiveContainer></ChartCard><ChartCard title="Cognitive skill balance" subtitle="Five skill signals, updated by completed practice"><ResponsiveContainer width="100%" height="100%"><RadarChart data={radar} outerRadius="76%"><PolarGrid stroke="var(--line)"/><PolarAngleAxis dataKey="skill" tick={{fill:'var(--muted)',fontSize:10}}/><PolarRadiusAxis domain={[0,100]} tick={false} axisLine={false}/><Radar name="Observed independence" dataKey="Observed" stroke="var(--teal)" fill="var(--teal)" fillOpacity={0.2}/><Radar name="Practised" dataKey="Practised" stroke="var(--violet)" fill="var(--violet)" fillOpacity={0.14}/><Tooltip contentStyle={{borderRadius:12,border:'1px solid var(--line)',background:'var(--card)',color:'var(--text)'}}/></RadarChart></ResponsiveContainer><div className="chart-legend"><i className="teal-dot"/> observed independence <i className="amber-dot"/> practiced</div></ChartCard></div><div className="bottom-panels"><div className="card start-card"><div className="start-icon"><Sparkles size={20}/></div><div><span className="eyebrow">A GOOD NEXT STEP</span><h3>{recommendations[0]?.title||'Try a quick recall challenge'}</h3><p>{recommendations[0]?.detail||'Spend a few minutes practicing from memory.'}</p><button className="text-action" onClick={()=>setSection('Challenges')}>Start a challenge <ArrowRight size={14}/></button></div></div><RecentActivity sessions={sessions}/></div></>}
  {section==='Balance sheet'&&<BalanceSheet user={user} setSection={setSection}/>}{section==='Cognitive Games'&&<GamePanel userId={user.id} userName={user.name} attempts={user.sessions} onComplete={onComplete}/>}{section==='AI Coach'&&<ChatPanel key="AI Coach" userId={user.id}/>}
 {section==='Challenges'&&<ChallengePanel user={user} onComplete={onComplete} onOpenCoach={()=>setSection('AI Coach')} notify={notify}/>}
 {section==='Focus session'&&<FocusSessionPanel user={user} onComplete={onComplete}/>}
 {section==='Wander break'&&<BreakSession user={user} onComplete={onComplete} rewardedToday={breakToday}/>}
 {section==='Credits'&&<Credits user={user} transactions={db.transactions.filter(t=>t.userId===user.id)} onSpend={(cost,level)=>{if(user.credits<cost){notify('Not enough Think Credits for that assistance level.');return}const next={...db,users:db.users.map(p=>p.id===user.id?{...p,credits:p.credits-cost}:p),transactions:[{id:keyId(),userId:user.id,amount:-cost,reason:`AI assistance · ${level}`,at:new Date().toISOString()},...db.transactions]};saveDb(next);notify(`${cost} credits used. External AI access is not included.`)}}/>}
 {section==='Progress'&&<ProgressView user={user} chartData={chartData} radar={radar}/>}
 </section></div>
}
function RecentActivity({sessions}:{sessions:Session[]}){return <div className="card recent-card"><div className="card-heading"><div><h3>Recent activity</h3><p>Your progress, one session at a time</p></div></div>{sessions.slice(0,4).map(s=><div className="recent-row" key={s.id}><span className={`recent-icon ${s.type}`}>{s.type==='focus'?<Focus size={15}/>:s.type==='break'?<Leaf size={15}/>:<Brain size={15}/>}</span><span><b>{s.title}</b><small>{new Date(s.date).toLocaleDateString()} · {s.durationMinutes} min</small></span><strong>{s.score}<small>/100</small></strong></div>)}</div>}
function BalanceSheet({user,setSection}:{user:Person;setSection:(s:string)=>void}){return <><div className="section-head"><div><span className="eyebrow">COGNITIVE BALANCE SHEET</span><h2>Patterns, with room to grow.</h2><p className="section-sub">An experimental indicator based on logged assistance and independent practice. It is not a validated psychological or medical measure.</p></div><button className="btn btn-primary" onClick={()=>setSection('Challenges')}>Practice a skill <ArrowRight size={15}/></button></div><div className="balance-detail-grid">{skills.map(s=>{const d=user.skills[s];return <div className="skill-detail card" key={s}><div className="skill-detail-top"><div className="metric-icon teal"><Brain size={17}/></div><span>LAST 30 DAYS</span></div><h3>{s}</h3><div className="debt-number">{d.debt}<small> observed debt</small></div><div className="progress-track debt"><i style={{width:`${d.debt}%`}}/></div><div className="repay-number">{d.repaid} <span>practice repayment</span></div><div className="progress-track"><i style={{width:`${d.repaid}%`}}/></div><p>{d.debt>30?'Try one independent practice session to begin lowering assistance patterns.':'Keep practicing independently to build a steady trend.'}</p><button className="text-action" onClick={()=>setSection('Challenges')}>Try a {s} challenge <ArrowRight size={14}/></button></div>})}</div><div className="disclaimer-strip"><ShieldCheck size={16}/><span>Debt and repayment are transparent prototype indicators, not validated measures of cognitive ability or health.</span></div></>}

function BreakSession({user,onComplete,rewardedToday}:{user:Person;onComplete:(s:Session)=>void;rewardedToday:number}){const [active,setActive]=useState(false),[seconds,setSeconds]=useState(0),[thought,setThought]=useState(''),[done,setDone]=useState(false),[startedAt,setStartedAt]=useState(0);useEffect(()=>{if(!active)return;const id=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(id)},[active]);const fmt=(s:number)=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;const finish=()=>{if(seconds<60){return}if(thought.trim().length<8)return;setActive(false);setDone(true);const eligible=rewardedToday<3;onComplete({id:keyId(),userId:user.id,type:'break',score:100,creditsEarned:eligible?1:0,date:new Date().toISOString(),durationMinutes:Math.floor(seconds/60),title:'Wander window'});};return <><div className="section-head"><div><span className="eyebrow">WANDER WINDOW</span><h2>Give your thoughts a little space.</h2><p className="section-sub">A short, gentle pause. This app can’t verify that you rested—only that a session was active and you recorded a thought.</p></div></div><div className="break-layout"><div className="break-illustration card"><div className="break-sun">☼</div><span className="eyebrow">A MOMENT FOR YOU</span><div className="break-timer">{fmt(seconds)}</div><p>{done?'A thought captured. Thank you for pausing.':active?'Let your mind wander. Notice something small.':'When you’re ready, start a two-minute pause.'}</p><div className="button-row center">{!active&&!done?<button className="btn btn-primary" onClick={()=>{setActive(true);setStartedAt(Date.now())}}>Start break <ArrowRight size={15}/></button>:active?<button className="btn btn-secondary" onClick={()=>{setActive(false);setSeconds(0);setThought("")}}>Abandon break</button>:<button className="btn btn-primary" onClick={()=>{setDone(false);setSeconds(0);setThought('')}}>Start another break</button>}</div><div className="break-limit"><Coins size={14}/> {Math.max(0,3-rewardedToday)} rewarded breaks left today</div></div><div className="break-prompt card"><span className="eyebrow">A SMALL REFLECTION</span><h3>{active?'What’s one thing you noticed?':'Your reflection appears during a break.'}</h3><p>A sound, a question, a moment of curiosity—anything that came to mind.</p><textarea disabled={!active} rows={5} value={thought} onChange={e=>setThought(e.target.value)} placeholder="Write a thought or question…"/><small>Private reflection · never shared with a supervisor</small><button disabled={!active||seconds<60||thought.trim().length<8} className="btn btn-primary full-btn" onClick={finish}>Complete break {seconds<60&&active&&<span className="button-hint">(keep the session active for 1 minute)</span>}</button>{!active&&<div className="break-credit"><Coins size={15}/><span>Earn 1 Think Credit for an eligible completed break. Maximum three per day. Abandoned breaks earn none.</span></div>}</div></div></>}

function Credits({user,transactions,onSpend}:{user:Person;transactions:State['transactions'];onSpend:(c:number,l:string)=>void}){const options=[{name:'Light hint',cost:1,desc:'A small nudge to keep going independently.'},{name:'Guided help',cost:3,desc:'A little more structure, with room to think.'},{name:'Deep explanation',cost:5,desc:'A fuller explanation to learn from.'}];return <><div className="section-head"><div><span className="eyebrow">THINK CREDITS WALLET</span><h2>Your effort, made visible.</h2><p className="section-sub">Credits reward practice. They can represent an in-app allowance, but do not guarantee unlimited access to any external AI service.</p></div></div><div className="wallet-hero card"><div><span className="eyebrow">AVAILABLE BALANCE</span><div className="wallet-balance"><Coins size={25}/>{user.credits}<small>Think Credits</small></div><p>Earn credits with completed challenges and eligible breaks.</p></div><div className="wallet-total"><div><span>Earned</span><b>+{transactions.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0)}</b></div><div><span>Spent</span><b>−{transactions.filter(t=>t.amount<0).reduce((n,t)=>n-t.amount,0)}</b></div></div></div><div className="credit-grid"><div className="card assistance-card"><div className="card-heading"><div><h3>Assistance levels</h3><p>Choose how much help you want</p></div><span className="metric-icon amber"><Sparkles size={17}/></span></div>{options.map(o=><div className="assist-row" key={o.name}><div><b>{o.name}</b><p>{o.desc}</p></div><button className="btn btn-secondary" onClick={()=>onSpend(o.cost,o.name)}><Coins size={14}/>{o.cost}</button></div>)}<p className="disclaimer">Prototype ledger only. No AI provider is connected; spending credits does not call an AI service.</p></div><div className="card transaction-card"><div className="card-heading"><div><h3>Recent transactions</h3><p>Reconciled against your credit balance</p></div></div>{transactions.length?transactions.slice(0,8).map(t=><div className="transaction-row" key={t.id}><span className={`transaction-mark ${t.amount>0?'positive':''}`}>{t.amount>0?'+':'−'}</span><span><b>{t.reason}</b><small>{new Date(t.at).toLocaleDateString()}</small></span><strong className={t.amount>0?'positive-text':''}>{money(t.amount)}</strong></div>):<div className="empty-state"><Coins size={22}/><p>Your credits and activity will appear here.</p></div>}</div></div></>}

function ProgressView({user,chartData,radar}:{user:Person;chartData:MemberDashProps['chartData'];radar:MemberDashProps['radar']}){const sessions=user.sessions;const memory=sessions.filter(s=>s.skill==='Memory');const gap=average(memory.map(s=>Math.abs((s.confidence||50)-(s.actual||s.score))));const completed=sessions.filter(s=>s.type==='mission').length;return <><div className="section-head"><div><span className="eyebrow">YOUR PROGRESS</span><h2>Notice the small changes.</h2><p className="section-sub">Recorded activity only. Demo accounts contain clearly seeded sample sessions.</p></div></div><div className="metric-grid four"><Metric label="CHALLENGES COMPLETED" value={`${completed}`} unit="" delta="recorded practice" tone="teal" icon={<Check size={17}/>}/><Metric label="ATTENTION TREND" value={`${average(sessions.filter(s=>s.type==='focus'||(s.type==='game'&&s.gameId==='focus')).map(s=>s.score))||'—'}`} unit="/100" delta="focus sessions" tone="violet" icon={<Focus size={17}/>}/><Metric label="RECALL TREND" value={`${average(memory.map(s=>s.score))||'—'}`} unit="/100" delta="memory challenges" tone="blue" icon={<Brain size={17}/>}/><Metric label="CONFIDENCE GAP" value={`${gap}`} unit="pts" delta="recall confidence vs score" tone="rose" icon={<Activity size={17}/>}/></div><div className="chart-grid"><ChartCard title="Attention trend" subtitle="Focus Rush and focus-session scores across the week"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="var(--line)"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis hide domain={[0,100]}/><Tooltip/><Line dataKey="Attention" stroke="var(--teal)" strokeWidth={2.5}/></LineChart></ResponsiveContainer></ChartCard><ChartCard title="Weekly debt-to-practice" subtitle="Experimental observed debt and logged practice"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="var(--line)"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'var(--muted)',fontSize:11}}/><YAxis hide/><Tooltip/><Area type="monotone" dataKey="Debt" stroke="var(--rose)" fill="var(--rose-soft)"/><Area type="monotone" dataKey="Repaid" stroke="var(--teal)" fill="var(--teal-soft)"/></AreaChart></ResponsiveContainer></ChartCard></div><div className="bottom-panels"><div className="card transaction-card"><div className="card-heading"><div><h3>Credits earned and spent</h3><p>Think Credit ledger totals</p></div></div><div className="credit-total-row"><div><small>Earned</small><b>+{sessions.reduce((n,s)=>n+s.creditsEarned,0)}</b></div><div><small>Spent</small><b>−{user.credits<0?0:Math.max(0,user.credits-26)}</b></div><div><small>Current</small><b>{user.credits}</b></div></div></div><RecentActivity sessions={sessions}/></div></>}
type MemberDashProps={chartData:{day:string;Attention:number|null;Recall:number|null;Earned:number;Debt:number;Repaid:number}[];radar:{skill:string;Observed:number;Practised:number}[]}
